const raw = $input.first().json;
const body = raw.body || raw;
const msg = body.message || body;
const conv = body.conversation || {};

let inputType = 'text';
let selectionId = '';
let selectionTitle = '';
let messageText = '';

if (msg.type === 'interactive') {
  const interactive = msg.interactive || {};
  if (interactive.type === 'button_reply') {
    inputType = 'button';
    selectionId = interactive.button_reply.id;
    selectionTitle = interactive.button_reply.title;
  } else if (interactive.type === 'list_reply') {
    inputType = 'list';
    selectionId = interactive.list_reply.id;
    selectionTitle = interactive.list_reply.title;
  }
} else if (msg.type === 'text') {
  const txt = msg.text || {};
  messageText = typeof txt === 'string' ? txt : (txt.body || '');
}

const phone = '+' + (conv.phone_number || msg.from || body.phone_number || body.phone || '');

return [{
  json: {
    phone_number: phone,
    conversation_id: conv.id || msg.from || body.phone_number || body.phone || '',
    contact_name: conv.contact_name || body.contact_name || '',
    input_type: inputType,
    selection_id: selectionId,
    selection_title: selectionTitle,
    message_text: messageText,
    media_url: null,
    message_id: null
  }
}];

const rawInput = $input.first().json;
const sessions = Array.isArray(rawInput) ? rawInput : (rawInput.body || []);
const session = Array.isArray(sessions) && sessions.length > 0 ? sessions[0] : null;
const payload = $('Normalize Payload').item.json;

let route = 'forward_agent';
let sessionId = null;
let templateSlug = 'kitchen-quotation';
let currentStep = null;
let formData = {};

if (session) {
  sessionId = session.id;
  templateSlug = session.template_slug;
  currentStep = session.current_step;
  formData = session.form_data || {};
  if (payload.input_type === 'button' || payload.input_type === 'list') {
    route = 'advance_step';
  } else {
    route = 'cancel_forward';
  }
} else {
  if (payload.input_type === 'button' || payload.input_type === 'list') {
    if (payload.selection_id === 'start_intake') {
      route = 'start_intake';
    } else if (payload.selection_id === 'human') {
      route = 'handoff';
    } else if (payload.selection_id === 'free_text') {
      route = 'forward_agent';
    } else {
      route = 'welcome';
    }
  } else {
    const text = (payload.message_text || '').toLowerCase();
    if (text.includes('cotizar') || text.includes('menu') || text.includes('hola') || text.includes('inicio') || text.includes('/start')) {
      route = 'welcome';
    } else {
      route = 'forward_agent';
    }
  }
}

return [{
  json: {
    route: route,
    session_id: sessionId,
    template_slug: templateSlug,
    current_step: currentStep,
    form_data: formData,
    phone_number: payload.phone_number,
    conversation_id: payload.conversation_id,
    contact_name: payload.contact_name,
    selection_id: payload.selection_id,
    selection_title: payload.selection_title,
    message_text: payload.message_text,
    input_type: payload.input_type,
    media_url: payload.media_url,
    message_id: payload.message_id
  }
}];

const rawInput = $input.first().json;
const templates = Array.isArray(rawInput) ? rawInput : (rawInput.body || []);
const template = Array.isArray(templates) && templates.length > 0 ? templates[0] : null;
const routeData = $('Route').item.json;

if (!template) {
  throw new Error('Template not found: ' + routeData.template_slug);
}

const def = template.definition || {};
const steps = def.steps || [];
const firstStepId = def.first_step || 'welcome';

return [{
  json: {
    phone_number: routeData.phone_number,
    conversation_id: routeData.conversation_id,
    template_slug: routeData.template_slug,
    current_step: firstStepId,
    form_data: {},
    step_def: steps.find(s => s.id === firstStepId),
    all_steps: steps,
    contact_name: routeData.contact_name
  }
}];

const rawInput = $input.first().json;
const templates = Array.isArray(rawInput) ? rawInput : (rawInput.body || []);
const template = Array.isArray(templates) && templates.length > 0 ? templates[0] : null;
const routeData = $('Route').item.json;

if (!template) {
  throw new Error('Template not found: ' + routeData.template_slug);
}

const def = template.definition || {};
const steps = def.steps || [];
const currentStepId = routeData.current_step;
const currentStep = steps.find(s => s.id === currentStepId);

if (!currentStep) {
  throw new Error('Step not found: ' + currentStepId);
}

// Validate selection against current step options
let isValid = false;
let selectedOption = null;

if (currentStep.type === 'interactive_button' && currentStep.options) {
  selectedOption = currentStep.options.find(o => o.id === routeData.selection_id);
  isValid = !!selectedOption;
} else if (currentStep.type === 'interactive_list' && currentStep.sections) {
  for (const section of currentStep.sections) {
    const row = section.rows.find(r => r.id === routeData.selection_id);
    if (row) {
      selectedOption = row;
      isValid = true;
      break;
    }
  }
}

if (!isValid) {
  // Invalid selection - re-send current step
  return [{
    json: {
      action: 'render',
      phone_number: routeData.phone_number,
      session_id: routeData.session_id,
      current_step: currentStepId,
      step_def: currentStep,
      form_data: routeData.form_data,
      contact_name: routeData.contact_name,
      template_slug: routeData.template_slug,
      error: 'Invalid selection: ' + routeData.selection_id
    }
  }];
}

// Update form data
const formData = { ...routeData.form_data };
if (currentStep.field) {
  if (currentStep.multi_repeat) {
    if (!formData[currentStep.field]) formData[currentStep.field] = [];
    formData[currentStep.field].push(routeData.selection_id);
  } else {
    formData[currentStep.field] = routeData.selection_id;
  }
}

// Determine next step
let nextStepId = selectedOption.next || currentStep.next;

// Handle special actions
if (nextStepId === '_exit_to_agent' || nextStepId === '_handoff' || nextStepId === '_cancel' || nextStepId === 'complete') {
  return [{
    json: {
      action: nextStepId,
      phone_number: routeData.phone_number,
      conversation_id: routeData.conversation_id,
      session_id: routeData.session_id,
      form_data: formData,
      template_slug: routeData.template_slug,
      contact_name: routeData.contact_name,
      message_text: routeData.message_text
    }
  }];
}

// Find next step definition
const nextStep = steps.find(s => s.id === nextStepId);
if (!nextStep) {
  throw new Error('Next step not found: ' + nextStepId);
}

return [{
  json: {
    action: 'render',
    phone_number: routeData.phone_number,
    session_id: routeData.session_id,
    current_step: nextStepId,
    step_def: nextStep,
    form_data: formData,
    template_slug: routeData.template_slug,
    contact_name: routeData.contact_name
  }
}];

const rawInput = $input.first().json;
const input = Array.isArray(rawInput) ? rawInput : (rawInput.body || rawInput);
const stepDef = input.step_def;
const formData = input.form_data || {};
const contactName = input.contact_name || '';

if (!stepDef) {
  throw new Error('No step definition');
}

// Build prompt with substitutions
let prompt = stepDef.prompt || 'Selecciona una opcion:';
prompt = prompt.replace(/\{\{contact_name\}\}/g, contactName);
for (const [key, value] of Object.entries(formData)) {
  let display = value;
  if (Array.isArray(value)) display = value.join(', ');
  prompt = prompt.replace(new RegExp('\\{\\{' + key + '\\}\\}', 'g'), display);
}

const phone = input.phone_number;
let payload = {};

if (stepDef.type === 'interactive_button') {
  const buttons = (stepDef.options || []).map(o => ({
    type: 'reply',
    reply: { id: o.id, title: o.title }
  }));
  payload = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: phone,
    type: 'interactive',
    interactive: {
      type: 'button',
      body: { text: prompt },
      action: { buttons: buttons.slice(0, 3) }
    }
  };
} else if (stepDef.type === 'interactive_list') {
  const sections = (stepDef.sections || []).map(sec => ({
    title: sec.title,
    rows: (sec.rows || []).map(r => ({
      id: r.id,
      title: r.title,
      description: r.description || ''
    }))
  }));
  payload = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: phone,
    type: 'interactive',
    interactive: {
      type: 'list',
      body: { text: prompt },
      action: {
        button: 'Ver opciones',
        sections: sections
      }
    }
  };
} else if (stepDef.type === '_complete') {
  payload = {
    messaging_product: 'whatsapp',
    recipient_type: 'individual',
    to: phone,
    type: 'text',
    text: { body: prompt }
  };
}

return [{
  json: {
    kapso_payload: payload,
    phone_number: phone
  }
}];
